      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not discuss excluding studies based on whether outcomes were measured versus reported, so this conditional requirement does not apply."
    },
    {
      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "Outcomes reported by two or more studies were pooled in a meta-analysis. ... A pooled odds ratio (OR) was estimated for dichotomous outcomes. ... The data of OMAS are presented as mean between-group difference (with 95% confidence interval).",
      "reason": "The manuscript specifies that outcomes reported by two or more studies were pooled in a meta-analysis, and describes the synthesis methods (pooled OR for dichotomous outcomes, mean between-group difference for OMAS) linked to the review objectives."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "NOT_APPLICABLE",
