{
  "item_id": "PRISMA_2020_10a",
  "elements": [
    {
      "element_id": "prisma_2020_10a_e1",
      "status": "PRESENT",
      "chunk_id": "text_7",
      "quote": "The safety of NOM during posttraumatic care management was evaluated using the reported number of complications up to one year after injury. Complications of NOM consisted of persistent joint stiffness, pressure injuries caused by orthosis, or casts (epidermal excoriation, dermal excoriation), persistent pain [Visual Analogue Scale (VAS) lower than 3], persistent perceived instability at final follow-up, failure of immobilization material (e.g. breakage), or clinically diagnosed DVT. Complications requiring surgical intervention were delayed or non-union, or secondary displacement.",
      "reason": "The manuscript lists and defines the outcome domains for safety (complications) and functional outcomes (PROMs like OMAS and AAOS are mentioned in text_8 and text_12)."
    },
    {
      "element_id": "prisma_2020_10a_e2",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "For the secondary outcome, functional outcome, 12 weeks follow-up was considered the most appropriate timing for measuring OMAS. Other time points were OMAS at 6 weeks or the closest shorter timing of follow-up (e.g. 4 weeks), and OMAS at 26 weeks or the closest timing of later time points (e.g. 52 weeks).",
      "reason": "The manuscript specifies the time frames for the functional outcome measures (OMAS)."
    },
    {
      "element_id": "prisma_2020_10a_e3",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not explicitly state whether all results compatible with each outcome domain were sought from the included studies."
    },
    {
      "element_id": "prisma_2020_10a_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "Since the requirement to state whether all compatible results were sought is missing, this conditional element cannot be evaluated, but there is no evidence that the authors had to select results due to an exhaustive search."
    },
    {
      "element_id": "prisma_2020_10a_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "There is no evidence of changes to outcome-domain inclusion, definitions, or importance."
    },
    {
