{
  "item_id": "PRISMA_2020_10b",
  "elements": [
    {
      "element_id": "prisma_2020_10b_e1",
      "status": "PRESENT",
      "chunk_id": "text_5",
      "quote": "The following paper-related data were extracted: first author, year of publication, country in which the study was conducted, and study design [e.g. cohort study, randomized clinical trial (RCT)]. Extracted patient-related data were: included number of patients, age in years, sex of included patients, number of patients treated with a removable orthosis, type of orthosis (e.g. walker, air-stirrup brace), number of patients treated with a cast, duration of NOM in weeks (e.g. immobilization in cast in weeks). Extracted diagnostic criteria to assess fracture stability were extracted: type of diagnostics (radiograph, CT, ultrasound), classification system (Lauge-Hansen, Weber), sub-classification (Supination External Rotation type II, Weber B), additional radiological criteria [Superior Clear Space (SCS) in millimetre (mm)], Medial Clear Space (MCS) in mm, MCS and SCS ratio, fibular dislocation in mm, MCS under external rotation stress in mm, additional clinical diagnostic criteria (e.g. medial side tenderness), time to performance diagnostics in days (e.g. at primary visit, or 10-14 days after trauma). The following weight-bearing related data were extracted: weight-bearing permission by a medical specialist (yes/no), percentage of allowed weight-bearing in the affected limb (0-100), time to start weight-bearing after injury in days, reported number and type of complications, including Confidence Intervals (CI) or, if CIs are unavailable p values, used scale and timing of reported functional outcomes (e.g. PROMs, including CIs and p values).",
      "reason": "The manuscript explicitly lists and defines the variables for which data were sought, including paper-related, patient-related, diagnostic, and weight-bearing related data."
    },
    {
      "element_id": "prisma_2020_10b_e2",
      "status": "PRESENT",
      "chunk_id": "text_9",
      "quote": "To perform a meta-analysis, missing means or SDs that were not reported in an article and which could not be retrieved after the attempt to contact the corresponding author were estimated if possible using the available information. If the range was available for outcome variables, the SD was estimated as range divided by 4 [27]. The SD was estimated from the standard error (SE) using the formula SE = SD/√ n , where n is the sample size. The SE was estimated from the 95% CI by dividing the width of the CI by 2 × 1.96 = 3.92 [27]. Data were converted into the same units if needed.",
      "reason": "The authors describe specific assumptions and methods used to estimate missing data (means, SDs, SEs) when they were not reported in the original articles."
    },
    {
      "element_id": "prisma_2020_10b_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript does not mention using a specific tool (like a standardized data extraction form template) to determine which data items to collect; therefore, this conditional requirement is not applicable."
    }
  ],
  "confidence": 100
}

